) values (
  '32051bf9-f11c-50df-a477-863729395f9f'::uuid, null, 'Mind Seize', 'commander', 'Mind Seize is an official Commander precon from C13, released 2013-11-01.', 'public', true, true,
  '83f9aeb8-05ba-49d9-a834-62f42fcd295b', 'Jeleva, Nephalia''s Scourge', 'Legendary Creature — Vampire Wizard', '{1}{U}{B}{R}',
