) values (
  'a616253f-5ac8-5407-baa5-89a207aa4bfd'::uuid, null, 'Sworn To Darkness', 'commander', 'Sworn To Darkness is an official Commander precon from C14, released 2014-11-07.', 'public', true, true,
  'bf472be9-f375-455e-a800-7af5258f4e59', 'Ob Nixilis of the Black Oath', 'Legendary Planeswalker — Nixilis', '{3}{B}{B}',
