) values (
  '13745218-e10b-5053-9811-fab7a77f2df8'::uuid, null, 'Swell the Host', 'commander', 'Swell the Host is an official Commander precon from C15, released 2015-11-13.', 'public', true, true,
  'ef1b62ff-dbb3-4500-9d64-a3047ce193ec', 'Ezuri, Claw of Progress', 'Legendary Creature — Phyrexian Elf Warrior', '{2}{G}{U}',
