) values (
  'cad5c5a6-8f1a-5c8f-a029-975fc721d960'::uuid, null, 'Stalwart Unity', 'commander', 'Stalwart Unity is an official Commander precon from C16, released 2016-11-11.', 'public', true, true,
  '97fa8615-2b6c-445a-bcaf-44a7e847bf65', 'Kynaios and Tiro of Meletis', 'Legendary Creature — Human Soldier', '{R}{G}{W}{U}',
  'https://cards.scryfall.io/normal/front/9/7/97fa8615-2b6c-445a-bcaf-44a7e847bf65.jpg', 'https://cards.scryfall.io/art_crop/front/9/7/97fa8615-2b6c-445a-bcaf-44a7e847bf65.jpg', ARRAY['W', 'U', 'R', 'G']::text[], ARRAY['W', 'U', 'R', 'G']::text[]
) on conflict (id) do update set
  owner_id = excluded.owner_id,
  name = excluded.name,
  format = excluded.format,
  notes = excluded.notes,
  visibility = excluded.visibility,
  allow_forks = excluded.allow_forks,
  is_precon = excluded.is_precon,
  commander_scryfall_id = excluded.commander_scryfall_id,
