) values (
  'd0a03afd-6e46-5a77-acc2-e216a4f34659'::uuid, null, 'Plunder the Graves', 'commander', 'Plunder the Graves is an official Commander precon from CMA, released 2017-06-09.', 'public', true, true,
  '17d6703c-ad79-457b-a1b5-c2284e363085', 'Meren of Clan Nel Toth', 'Legendary Creature — Human Shaman', '{2}{B}{G}',
  'https://cards.scryfall.io/normal/front/1/7/17d6703c-ad79-457b-a1b5-c2284e363085.jpg', 'https://cards.scryfall.io/art_crop/front/1/7/17d6703c-ad79-457b-a1b5-c2284e363085.jpg', ARRAY['B', 'G']::text[], ARRAY['B', 'G']::text[]
) on conflict (id) do update set
  owner_id = excluded.owner_id,
  name = excluded.name,
  format = excluded.format,
  notes = excluded.notes,
  visibility = excluded.visibility,
