) values (
  '77c7f7ec-5995-54b2-8e3d-82ecd573f557'::uuid, null, 'Arcane Wizardry', 'commander', 'Arcane Wizardry is an official Commander precon from C17, released 2017-08-25.', 'public', true, true,
  '7c6e803a-451c-4aa6-97a2-400077f32c47', 'Inalla, Archmage Ritualist', 'Legendary Creature — Human Wizard', '{2}{U}{B}{R}',
  'https://cards.scryfall.io/normal/front/7/c/7c6e803a-451c-4aa6-97a2-400077f32c47.jpg', 'https://cards.scryfall.io/art_crop/front/7/c/7c6e803a-451c-4aa6-97a2-400077f32c47.jpg', ARRAY['U', 'B', 'R']::text[], ARRAY['U', 'B', 'R']::text[]
) on conflict (id) do update set
